cards.solution:
class Pelanggan:
    def __init__(self, nama):
        self.nama = nama
    def bayar(self, total):
        return total
    def info(self, total):
        return f"{self.nama} bayar {self.bayar(total)}"

class Member(Pelanggan):
    def bayar(self, total):
        return total - total * 10 // 100

jenis = input()
nama = input()
total = int(input())
p = Member(nama) if jenis == "member" else Pelanggan(nama)
print(p.info(total))

